"use client"

import { cn } from "@/lib/utils"
import { EntityImage } from "@/registry/mrdoge-ui/entity-image/entity-image"
import {
  LiveIndicator,
  type LiveIndicatorStatus,
} from "@/registry/mrdoge-ui/live-indicator/live-indicator"
import {
  OddsSelector,
  type OddsOption,
} from "@/registry/mrdoge-ui/odds-selector/odds-selector"

export interface MatchCardTeam {
  name: string
  logoUrl?: string
  /** Shown as a small red-card marker (position set by MatchCardProps.redCardPosition) once the match is live or finished. */
  redCards?: number
}

export interface MatchCardProps {
  status: LiveIndicatorStatus
  kickoff?: Date | string
  elapsed?: string
  home: MatchCardTeam
  away: MatchCardTeam
  homeScore?: number
  awayScore?: number
  /**
   * Where the red-card marker renders relative to each team row: "left"
   * (next to the team name) or "right" (next to the score).
   *
   * @defaultValue "right"
   */
  redCardPosition?: "left" | "right"
  /** Renders a compact odds row below the match when provided. */
  odds?: OddsOption[]
  selectedOddsId?: string
  onSelectOdds?: (id: string) => void
  className?: string
}

function RedCardIndicator({ count }: { count: number }) {
  return (
    <div className="flex items-center gap-0.5">
      {count > 1 ? (
        <span className="text-[11px] font-bold tabular-nums text-destructive">x{count}</span>
      ) : null}
      <span className="block h-2.5 w-[7px] shrink-0 rounded-[1.5px] bg-destructive" />
    </div>
  )
}

function TeamRow({
  team,
  score,
  showScore,
  showRedCards,
  redCardPosition,
  dimmed,
}: {
  team: MatchCardTeam
  score?: number
  showScore: boolean
  showRedCards: boolean
  redCardPosition: "left" | "right"
  /** True for the losing side once the match is finished. */
  dimmed: boolean
}) {
  const redCard =
    showRedCards && team.redCards ? <RedCardIndicator count={team.redCards} /> : null

  return (
    <div className="flex items-center justify-between gap-2">
      <div className="flex min-w-0 items-center gap-2">
        <EntityImage src={team.logoUrl} name={team.name} size="sm" />
        <span className="truncate text-sm font-medium">{team.name}</span>
        {redCardPosition === "left" ? redCard : null}
      </div>
      <div className="flex shrink-0 items-center gap-2.5">
        {redCardPosition === "right" ? redCard : null}
        {showScore ? (
          <span
            className={cn(
              "text-sm font-semibold tabular-nums",
              dimmed && "text-muted-foreground"
            )}
          >
            {score ?? 0}
          </span>
        ) : null}
      </div>
    </div>
  )
}

export function MatchCard({
  status,
  kickoff,
  elapsed,
  home,
  away,
  homeScore,
  awayScore,
  redCardPosition = "right",
  odds,
  selectedOddsId,
  onSelectOdds,
  className,
}: MatchCardProps) {
  const showScore = status !== "scheduled"
  const showRedCards = status !== "scheduled"
  const isFinished = status === "finished"
  const hasScores = homeScore != null && awayScore != null
  const homeLost = isFinished && hasScores && homeScore < awayScore
  const awayLost = isFinished && hasScores && awayScore < homeScore

  return (
    <div className={cn("w-full rounded-xl border bg-card text-card-foreground", className)}>
      <div className="flex gap-3 px-3 py-3">
        <div className="flex w-11 shrink-0 items-center justify-center border-r pr-3 text-center">
          <LiveIndicator variant="plain" status={status} kickoff={kickoff} elapsed={elapsed} />
        </div>
        <div className="flex min-w-0 flex-1 flex-col justify-center gap-2.5">
          <TeamRow
            team={home}
            score={homeScore}
            showScore={showScore}
            showRedCards={showRedCards}
            redCardPosition={redCardPosition}
            dimmed={homeLost}
          />
          <TeamRow
            team={away}
            score={awayScore}
            showScore={showScore}
            showRedCards={showRedCards}
            redCardPosition={redCardPosition}
            dimmed={awayLost}
          />
        </div>
      </div>
      {odds && odds.length > 0 ? (
        <div className="border-t px-3 py-3">
          <OddsSelector
            options={odds}
            selectedId={selectedOddsId}
            onSelect={onSelectOdds}
            className="w-full"
          />
        </div>
      ) : null}
    </div>
  )
}

import { Clock, Pause } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"

export type LiveIndicatorStatus =
  | "scheduled"
  | "live"
  | "paused"
  | "intermission"
  | "interrupted"
  | "finished"

export interface LiveIndicatorProps {
  status: LiveIndicatorStatus
  /** Kickoff time, shown when status is "scheduled". */
  kickoff?: Date | string
  /**
   * Elapsed match clock, shown when status is "live", "paused",
   * "intermission", or "interrupted" (e.g. "67'", "HT").
   */
  elapsed?: string
  /**
   * "badge" (default) renders a filled pill, for standalone use. "plain"
   * renders just the colored label with no background, for dense layouts
   * like Match Card's status column.
   */
  variant?: "badge" | "plain"
  className?: string
}

function formatKickoff(kickoff: Date | string) {
  const date = typeof kickoff === "string" ? new Date(kickoff) : kickoff
  return date.toLocaleTimeString(undefined, {
    hour: "numeric",
    minute: "2-digit",
  })
}

function formatKickoffDate(kickoff: Date | string) {
  const date = typeof kickoff === "string" ? new Date(kickoff) : kickoff
  return date.toLocaleDateString(undefined, {
    day: "2-digit",
    month: "2-digit",
  })
}

const stoppedPlayLabel: Record<"paused" | "intermission" | "interrupted", string> = {
  paused: "Paused",
  intermission: "Intermission",
  interrupted: "Interrupted",
}

export function LiveIndicator({
  status,
  kickoff,
  elapsed,
  variant = "badge",
  className,
}: LiveIndicatorProps) {
  if (variant === "plain") {
    if (status === "live") {
      return (
        <span className={cn("text-xs font-bold leading-tight text-destructive tabular-nums", className)}>
          {elapsed ?? "LIVE"}
        </span>
      )
    }

    if (status === "paused" || status === "intermission" || status === "interrupted") {
      return (
        <span
          className={cn(
            "text-xs font-bold leading-tight text-amber-600 tabular-nums dark:text-amber-400",
            className
          )}
        >
          {elapsed ?? stoppedPlayLabel[status]}
        </span>
      )
    }

    if (status === "finished") {
      return (
        <div className={cn("flex flex-col items-center gap-px", className)}>
          <span className="text-xs font-bold leading-tight text-muted-foreground tabular-nums">
            {elapsed ?? "FT"}
          </span>
          {kickoff ? (
            <span className="text-xs leading-tight text-muted-foreground tabular-nums">
              {formatKickoffDate(kickoff)}
            </span>
          ) : null}
        </div>
      )
    }

    return (
      <span className={cn("text-xs font-medium leading-tight text-muted-foreground tabular-nums", className)}>
        {kickoff ? formatKickoff(kickoff) : "—"}
      </span>
    )
  }

  if (status === "live") {
    return (
      <Badge
        variant="destructive"
        className={cn("gap-1.5 border-transparent bg-destructive text-destructive-foreground", className)}
      >
        <span className="relative flex size-1.5">
          <span className="absolute inline-flex size-full animate-ping rounded-full bg-destructive-foreground/60" />
          <span className="relative inline-flex size-1.5 rounded-full bg-destructive-foreground" />
        </span>
        {elapsed ?? "LIVE"}
      </Badge>
    )
  }

  if (status === "paused" || status === "intermission" || status === "interrupted") {
    return (
      <Badge
        variant="outline"
        className={cn(
          "gap-1.5 border-transparent bg-amber-500/15 text-amber-600 dark:text-amber-400",
          className
        )}
      >
        <Pause className="size-3" />
        {elapsed ?? stoppedPlayLabel[status]}
      </Badge>
    )
  }

  if (status === "finished") {
    return (
      <Badge variant="secondary" className={className}>
        Finished
      </Badge>
    )
  }

  return (
    <Badge variant="outline" className={cn("gap-1", className)}>
      <Clock className="size-3" />
      {kickoff ? formatKickoff(kickoff) : "Scheduled"}
    </Badge>
  )
}

"use client"

import type { ComponentType } from "react"
import { Minus, TrendingDown, TrendingUp } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export type OddsMovement = "up" | "down" | "flat"

export interface OddsOption {
  id: string
  /** Selection label, e.g. "1", "X", "2" or "Home", "Away". */
  label: string
  /** Formatted price, e.g. "1.85". */
  price: string
  movement?: OddsMovement
  suspended?: boolean
}

export interface OddsSelectorProps {
  options: OddsOption[]
  selectedId?: string
  onSelect?: (id: string) => void
  className?: string
}

const movementIcon: Record<OddsMovement, ComponentType<{ className?: string }>> = {
  up: TrendingUp,
  down: TrendingDown,
  flat: Minus,
}

const movementColor: Record<OddsMovement, string> = {
  up: "text-emerald-600 dark:text-emerald-500",
  down: "text-destructive",
  flat: "text-muted-foreground",
}

export function OddsSelector({
  options,
  selectedId,
  onSelect,
  className,
}: OddsSelectorProps) {
  return (
    <div className={cn("grid auto-cols-fr grid-flow-col gap-2", className)}>
      {options.map((option) => {
        const MovementIcon = option.movement
          ? movementIcon[option.movement]
          : null
        const selected = option.id === selectedId

        return (
          <Button
            key={option.id}
            type="button"
            variant={selected ? "default" : "outline"}
            disabled={option.suspended}
            onClick={() => onSelect?.(option.id)}
            className="h-auto flex-col gap-0.5 py-1.5"
          >
            <span className="text-xs font-normal opacity-80">
              {option.label}
            </span>
            <span className="flex items-center gap-1 text-sm font-semibold">
              {option.suspended ? "—" : option.price}
              {MovementIcon && !option.suspended ? (
                <MovementIcon
                  className={cn(
                    "size-3",
                    selected ? "opacity-90" : movementColor[option.movement!]
                  )}
                />
              ) : null}
            </span>
          </Button>
        )
      })}
    </div>
  )
}

"use client"

import { useState } from "react"
import { cn } from "@/lib/utils"

export interface EntityImageProps {
  src?: string | null
  /** Used for the alt text and the initials fallback. */
  name: string
  size?: "sm" | "default" | "lg"
  className?: string
}

const sizeClass: Record<NonNullable<EntityImageProps["size"]>, string> = {
  sm: "size-5",
  default: "size-8",
  lg: "size-10",
}

/**
 * Just the image — no background, border, or corner radius, so team crests
 * and region flags render at their native shape. Pass a `className` (e.g.
 * `size-6`) to override the size; it takes precedence over `size`.
 */
export function EntityImage({ src, name, size = "default", className }: EntityImageProps) {
  const [errored, setErrored] = useState(false)

  if (!src || errored) {
    return (
      <span
        className={cn(
          "flex shrink-0 items-center justify-center rounded-full bg-muted text-[0.6rem] font-medium text-muted-foreground",
          sizeClass[size],
          className
        )}
      >
        {name.slice(0, 2).toUpperCase()}
      </span>
    )
  }

  return (
    // eslint-disable-next-line @next/next/no-img-element -- framework-agnostic registry component, no next/image dependency
    <img
      src={src}
      alt={name}
      className={cn("shrink-0 object-contain", sizeClass[size], className)}
      onError={() => setErrored(true)}
    />
  )
}
